              <img
                src={project.image}
                alt={project.title}
                className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700"
              />
              <div className="absolute inset-0 bg-black/60 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center gap-4">
                <motion.a 
                  href={project.link}
                  whileHover={{ scale: 1.1 }}
                  className="p-4 bg-cyan-500 rounded-full text-black shadow-lg"
                >
                  <Play size={24} fill="currentColor" />
                </motion.a>
              </div>

              <div className="absolute top-4 right-4 z-20 flex gap-2">
                <a href={project.link} className="p-2.5 bg-black/80 backdrop-blur-md rounded-xl text-white hover:text-cyan-400 transition-colors border border-white/10">
                  <ExternalLink size={18} />
                </a>
              </div>
            </div>

            <div className="p-8 space-y-4">
              <div className="flex flex-wrap gap-2">
                {project.tech.map(t => (
                  <span key={t} className="text-[10px] font-bold uppercase tracking-widest text-cyan-400 bg-cyan-500/10 px-2 py-1 rounded-md border border-cyan-500/20">
                    {t}
                  </span>
                ))}
              </div>
              <h3 className="text-2xl font-bold text-white group-hover:text-cyan-400 transition-colors font-heading uppercase">{project.title}</h3>
              <p className="text-gray-400 text-sm leading-relaxed">
                {project.description}
              </p>

              <div className="pt-4 flex items-center justify-between">
                <SparkleButton text="VIEW_LIVE" href={project.link} className="!text-[10px] !px-4 !py-2" />
                <a href="#" className="flex items-center gap-2 text-xs font-bold text-gray-500 hover:text-white transition-colors uppercase tracking-widest">
                  <Github size={16} />
                  Codebase
                </a>
              </div>
            </div>
          </motion.div>
        ))}
      </div>

      <div className="mt-20 text-center">
        <SparkleButton text="SEE_ALL_PROJECTS_ON_FIVERR" href="https://fiverr.com/alvy" className="mx-auto" />
      </div>
    </div>
  );
};

export default Projects;

